import { useEffect, useRef, useState } from 'preact/hooks';
import { addLayer, ask, canInsertLayer, closeDialog, draggedLayer, insertLayer, layerDrop, layerName, profile, removeLayer, selectedLayer, selectedSlot, swapLayers, updateProfile } from '../store';
import { dropPosition } from '../drag';
import { maxLayers } from '../../model/constants';
import { IconChevron, IconPlus, IconTrash } from './Icons';

function AddLayerMenu() {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const itemRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!open) return;
    itemRef.current?.focus();
    const close = (event: PointerEvent) => {
      if (!ref.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener('pointerdown', close);
    return () => document.removeEventListener('pointerdown', close);
  }, [open]);
  return (
    <div class="menu layer-add-menu" ref={ref} onBlur={(event) => {
      if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false);
    }} onKeyDown={(event) => {
      if (event.key === 'Escape' && open) {
        event.preventDefault();
        setOpen(false);
        triggerRef.current?.focus();
      } else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        event.preventDefault();
        setOpen(true);
        itemRef.current?.focus();
      }
    }}>
      <div class="layer-add-buttons">
        <button type="button" class="tab tab-add" onClick={() => { setOpen(false); addLayer(); }} title="Create a new blank layer"><IconPlus /> Add Layer</button>
        <button type="button" class="tab tab-add layer-add-trigger" ref={triggerRef} aria-label="More Layer Options" title="More Layer Options" aria-haspopup="menu" aria-expanded={open} aria-controls={open ? 'layer-add-options' : undefined} onClick={() => setOpen(!open)}><IconChevron /></button>
      </div>
      {open && <div class="menu-list" id="layer-add-options" role="menu" aria-label="Layer Options">
        <button type="button" role="menuitem" ref={itemRef} onClick={() => {
          setOpen(false);
          triggerRef.current?.focus();
          addLayer('duplicate');
        }}>Duplicate Current Layer</button>
      </div>}
    </div>
  );
}

export function LayerTabs() {
  const p = profile.value!;
  const current = selectedLayer.value;
  const draggingStartup = useRef(false);
  const clearDrag = () => { draggingStartup.current = false; draggedLayer.value = null; layerDrop.value = null; };
  const gapTarget = (event: DragEvent): { index: number; position: 'before' | 'after' } | null => {
    const tabs = Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('.tab:not(.tab-add)'));
    let closest: { index: number; position: 'before' | 'after'; distance: number } | null = null;
    tabs.forEach((tab, index) => {
      const rect = tab.getBoundingClientRect();
      for (const position of ['before', 'after'] as const) {
        const x = position === 'before' ? rect.left : rect.right;
        const y = Math.max(rect.top, Math.min(event.clientY, rect.bottom));
        const distance = Math.hypot(event.clientX - x, event.clientY - y);
        if (!closest || distance < closest.distance) closest = { index, position, distance };
      }
    });
    return closest;
  };
  const removeSelected = () => {
    ask({
      title: `Remove ${layerName(current)}?`,
      body: `All local chords and bindings on this layer will be deleted. Global chords will be kept. Timers assigned to this layer will need a new layer assignment.${p.startupLayer === current ? '\nLayer 1 will become the new startup layer.' : ''}\nNothing changes on the device until you save.`,
      actions: [
        { label: 'Cancel', tone: 'neutral', onSelect: closeDialog },
        { label: 'Remove Layer', tone: 'danger', onSelect: () => { removeLayer(current); closeDialog(); } },
      ],
    });
  };
  return (
    <div class="layer-tabs-row">
    <div class="tabs" role="tablist" aria-label="Layers" onDragOver={(event) => {
      if ((event.target as HTMLElement).closest('.tab')) return;
      const source = draggedLayer.value;
      const target = gapTarget(event);
      if (source !== null && target && canInsertLayer(source, target.index, target.position)) {
        event.preventDefault();
        layerDrop.value = target;
        if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
      } else layerDrop.value = null;
    }} onDrop={(event) => {
      if ((event.target as HTMLElement).closest('.tab')) return;
      event.preventDefault();
      const source = draggedLayer.value;
      const target = gapTarget(event);
      if (source !== null && target) insertLayer(source, target.index, target.position);
      clearDrag();
    }}>
      {p.layers.map((_, i) => {
        const active = selectedLayer.value === i;
        const intent = layerDrop.value?.index === i ? layerDrop.value.position : null;
        return (
          <button
            key={i}
            role="tab"
            aria-selected={active}
            class={`tab ${active ? 'tab-active' : ''} ${draggedLayer.value === i ? 'is-dragging' : ''} ${intent === 'swap' ? 'is-drop-target' : ''}`}
            onClick={() => { selectedLayer.value = i; if (selectedSlot.value && selectedSlot.value.layer !== i) selectedSlot.value = null; }}
            title="Drop in the center to swap, or at an edge to insert"
            draggable
            onDragStart={(event) => { draggedLayer.value = i; event.dataTransfer?.setData('application/x-macropad-layer', 'move'); if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move'; }}
            onDragEnd={clearDrag}
            onDragOver={(event) => {
              if (draggingStartup.current) {
                event.preventDefault();
                event.stopPropagation();
                layerDrop.value = { index: i, position: 'swap' };
                if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
                return;
              }
              const source = draggedLayer.value;
              const position = dropPosition(event, 'horizontal');
              const valid = source !== null && (position === 'swap' ? source !== i : canInsertLayer(source, i, position));
              if (!valid) { layerDrop.value = null; if (event.dataTransfer) event.dataTransfer.dropEffect = 'none'; return; }
              event.preventDefault();
              layerDrop.value = { index: i, position };
              if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
            }}
            onDragLeave={(event) => {
              if (draggingStartup.current && !(event.currentTarget as HTMLElement).contains(event.relatedTarget as Node | null)) layerDrop.value = null;
            }}
            onDrop={(event) => {
              event.preventDefault();
              if (draggingStartup.current) {
                event.stopPropagation();
                if (profile.value!.startupLayer !== i) updateProfile(draft => { draft.startupLayer = i; });
                clearDrag();
                return;
              }
              const source = draggedLayer.value;
              const position = layerDrop.value?.index === i ? layerDrop.value.position : dropPosition(event, 'horizontal');
              if (source !== null) {
                if (position === 'swap') swapLayers(source, i);
                else insertLayer(source, i, position);
              }
              clearDrag();
            }}
          >
            <span class="tab-name">{layerName(i)}</span>
            {p.startupLayer === i && <span class="tab-badge" title="Drag to another layer tab to change the startup layer" draggable
              onDragStart={(event) => {
                event.stopPropagation();
                clearDrag();
                draggingStartup.current = true;
                event.dataTransfer?.setData('application/x-macropad-startup-layer', 'move');
                if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
              }}
              onDragEnd={(event) => { event.stopPropagation(); clearDrag(); }}
            >start</span>}
            {intent === 'before' || intent === 'after' ? <span class={`drop-line drop-line-${intent}`} aria-hidden="true" /> : null}
          </button>
        );
      })}
      {p.layers.length < maxLayers(p.variant) && (
        <AddLayerMenu />
      )}
    </div>
    <button class="btn btn-icon btn-danger layer-delete" aria-label={`Remove ${layerName(current)}`} title={p.layers.length === 1 ? 'At least one layer is required' : `Remove ${layerName(current)}`} disabled={p.layers.length === 1} onClick={removeSelected}><IconTrash /></button>
    </div>
  );
}
